/**
 * hermes-lg-end-cycle
 * Self-contained Hermes Desktop plugin — plays a custom MP3 when the
 * agent finishes a turn, replacing the built-in synthesized chime.
 *
 * The MP3 is embedded as a data URL so the plugin is a single file.
 * No external assets, no filesystem dependencies.
 */

import { host } from '@hermes/plugin-sdk'

// Embedded MP3 (~3.4s, loopable) — encoded as a data URL so the plugin
// is self-contained. Generated from end-cycle.mp3.
const DATA_URL = "data:audio/mpeg;base64,"

let audio = null
let initialized = false

function getAudio() {
  if (!audio) {
    audio = new Audio(DATA_URL)
    audio.preload = 'auto'
    audio.loop = false
  }
  return audio
}

export default {
  id: 'lg-end-cycle',
  name: 'LG End Cycle Sound',

  register() {
    host.onEvent('message.complete', () => {
      const el = getAudio()
      el.currentTime = 0
      void el.play().catch(() => {})
    })
  },
}
